<script lang="ts">
  import { onMount } from 'svelte'; import { goto } from '$app/navigation'; import { api } from '$lib/api'; import { apiError, type StudentSession } from '$lib/student-session';
  let session: StudentSession | null = null; let accepted = false; let error = ''; let loading = true; let saving = false;
  onMount(async () => { try { session = await api<StudentSession>('/api/student/auth/me'); if (!session.disclaimerRequired) await goto('/student'); } catch { await goto('/student/login'); } finally { loading = false; } });
  async function submit() { if (!accepted) return; saving = true; error = ''; try { await api('/api/student/disclaimer', { method: 'POST', body: JSON.stringify({ accepted: true, disclaimerVersion: 'student-profile-v2' }) }); await goto('/student'); } catch (e) { error = apiError(e); } finally { saving = false; } }
</script>
<svelte:head><title>Task Karate | Profile acknowledgment</title></svelte:head>
<main class="auth-stage"><section class="disclaimer-frame">{#if loading}<p>Checking your secure session…</p>{:else}<span class="student-eyebrow">PROFILE ACCESS / FINAL STEP</span><h1>Before you open<br />{session?.displayName ?? 'your'}’s page.</h1><p>Review and accept these terms before opening the supervised student profile.</p><label class="acknowledgment"><input type="checkbox" bind:checked={accepted} /><span>By selecting “Accept & open profile,” I agree to access this profile only for authorized Task Karate purposes. I will keep student and guardian information, credentials, and anything displayed here confidential, will not copy or share it without authorization, and will report suspected misuse promptly. I understand that misuse may result in immediate loss of access and other available remedies.</span></label>{#if error}<div class="error" role="alert">{error}</div>{/if}<div class="disclaimer-actions"><a class="outline-button" href="/schedule">Cancel</a><button class="primary-button" disabled={!accepted || saving} on:click={submit}>{saving ? 'Opening…' : 'Accept & open profile'}</button></div>{/if}</section></main>
